def accepted(solver: mathopt.SolverType, model: mathopt.Model, params: mathopt.SolveParameters) -> bool:
    try:
        solve(model, solver, params)
        return True
    except Exception:                    # the refusal; read_refusal.py shows how to read why
        return False


